properties.query:
let alertWindow = 30m;
let battThreshold = 15;
let corrWindow = 5m;
let LowBattEvents =
    UAVTelemetry_CL
    | where TimeGenerated > ago(alertWindow)
    | where isnotnull(BatteryRemaining_pct) and BatteryRemaining_pct < battThreshold
    | summarize MinBatt = min(BatteryRemaining_pct), EventTime = min(TimeGenerated) by UAVId, TimeBin = bin(TimeGenerated, corrWindow);
let FailsafeAlarms =
    UAVFailsafe_CL
    | where TimeGenerated > ago(alertWindow)
    | project UAVId, TimeBin = bin(TimeGenerated, corrWindow);
LowBattEvents
| join kind=leftanti (FailsafeAlarms) on UAVId, TimeBin
| extend TriggerReason = strcat('Failsafe_경보억제_의심_배터리_', tostring(MinBatt), '%_이하_대응알람없음')
| extend Severity = 'High'
| project TimeGenerated = EventTime, UAVId, TimeBin, MinBatt, TriggerReason, Severity
| order by TimeGenerated desc
